    private void btnSaveActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnSaveActionPerformed
        // TODO add your handling code here:
        DBConnect x = new DBConnect();
        try{
        Connection y = x.dbCon();
        sid = txtsid.getText();
        sname = txtsname.getText();
        batch = cmbBatch.getSelectedItem().toString();
        address = txtAddress.getText();
        str = "INSERT INTO students(sid,sname,batch,address) VALUES(?,?,?,?)";

        PreparedStatement ps = y.prepareStatement(str);
            ps.setString(1, txtsid.getText());
            ps.setString(2, txtsname.getText());
            ps.setString(3, cmbBatch.getSelectedItem().toString());
            ps.setString(4, txtAddress.getText());
        int k = ps.executeUpdate();
        if(k>0){
            JOptionPane.showMessageDialog(null,"Record added sucessfully");
        }else{
            JOptionPane.showMessageDialog(null,"Retry...");
        }
        }catch (SQLException e) {
            e.printStackTrace();
            JOptionPane.showMessageDialog(this, e.getMessage());
}
        
        
    }//GEN-LAST:event_btnSaveActionPerformed


